window.CATEGORIES = [{"id": "philosophy", "name": "Философия и взрослые смыслы", "emoji": "🧠"}, {"id": "humor", "name": "Юмор и абсурд", "emoji": "😄"}, {"id": "adventure", "name": "Приключения", "emoji": "🗺️"}, {"id": "friendship", "name": "Дружба и отношения", "emoji": "🤝"}, {"id": "romance", "name": "Любовь и романтика", "emoji": "❤️"}, {"id": "science", "name": "Наука и изобретения", "emoji": "🔬"}, {"id": "sport", "name": "Спорт и здоровье", "emoji": "⚽"}, {"id": "art", "name": "Творчество и искусство", "emoji": "🎨"}, {"id": "spooky", "name": "Мистика и страшилки", "emoji": "👻"}, {"id": "holiday", "name": "Праздники", "emoji": "🎉"}, {"id": "edu", "name": "Обучающие", "emoji": "📚"}, {"id": "everyday", "name": "Житейские истории", "emoji": "🏡"}];
